static int raw_build_board(const char *dtb_path)
{
	AthrillDeviceBuildOptions options;
	AthrillDeviceHostValue host = {"DEVICE_CONFIG_STM32_ACTUATOR_FILE", pwm_trace_path};
	memset(&target, 0, sizeof(target));
	memset(&options, 0, sizeof(options));
	options.dtb_path = dtb_path;
	options.target_compatibles = target_compatibles;
	options.target_compatible_count = sizeof(target_compatibles) / sizeof(target_compatibles[0]);
	options.maximum_dtb_size = 16U * 1024U * 1024U;
	options.host_values = &host;
	options.host_value_count = 1U;
	(void)plugin_path;

	return athrill_device_build(&options, &target_ops, &target, &runtime);
}

static char *read_capture(FILE *stream)
{
	long length;
	char *text;
	if (fseek(stream, 0L, SEEK_END) != 0 || (length = ftell(stream)) < 0 ||
	    fseek(stream, 0L, SEEK_SET) != 0) return NULL;
	text = malloc((size_t)length + 1U);
	if (text == NULL) return NULL;
	if (length != 0 && fread(text, 1U, (size_t)length, stream) != (size_t)length) {
		free(text); return NULL;
	}
	text[length] = 0;
	return text;
}

static int capture_build(const char *dtb_path, Capture *capture)
{
	FILE *out = tmpfile(), *err = tmpfile();
	int saved_out, saved_err, result;
	if (out == NULL || err == NULL) return -1;
	fflush(NULL);
	saved_out = dup(STDOUT_FILENO); saved_err = dup(STDERR_FILENO);
	if (saved_out < 0 || saved_err < 0 || dup2(fileno(out), STDOUT_FILENO) < 0 ||
	    dup2(fileno(err), STDERR_FILENO) < 0) return -1;
	result = raw_build_board(dtb_path);
	fflush(NULL);
	(void)dup2(saved_out, STDOUT_FILENO); (void)dup2(saved_err, STDERR_FILENO);
	(void)close(saved_out); (void)close(saved_err);
	capture->out = read_capture(out); capture->err = read_capture(err);
	fclose(out); fclose(err);
	return capture->out != NULL && capture->err != NULL ? result : -1;
}

static void free_capture(Capture *capture)
{ free(capture->out); free(capture->err); capture->out = NULL; capture->err = NULL; }

static int build_board(void)
{
	Capture capture = {0};
	int result;
	free(captured_stderr); captured_stderr = NULL;
	result = capture_build(board_dtb_path, &capture);
	free(capture.out); captured_stderr = capture.err;
	return result;
}

static uint32 count_lines(const char *text, const char *prefix)
{
	uint32 count = 0U;
	const char *at = text;
	while (at != NULL && (at = strstr(at, prefix)) != NULL) { count++; at += strlen(prefix); }
	return count;
}

static uint32 count_model_path(const char *text, const char *path)
{
	char needle[512];
	(void)snprintf(needle, sizeof(needle), "DEVICE_MODEL path=%s compatible=", path);
	return count_lines(text, needle);
}

static int mmio_set_matches(const ExpectedWindow *expected, uint32 count)
{
	uint32 i, j, found;
	if (target.mmio_count != count) return 0;
	for (i = 0U; i < count; i++) {
		found = 0U;
		for (j = 0U; j < target.mmio_count; j++)
			if (target.mmio[j].address == expected[i].address &&
			    target.mmio[j].size == expected[i].size) found++;
		if (found != 1U) return 0;
	}
	return 1;
}

static int mmio_pairwise_disjoint(void)
{
	uint32 i, j;
	for (i = 0U; i < target.mmio_count; i++)
		for (j = 0U; j < i; j++)
			if (target.mmio[i].address < target.mmio[j].address + target.mmio[j].size &&
			    target.mmio[j].address < target.mmio[i].address + target.mmio[i].size) return 0;
	return 1;
}

static int find_irq(const char *provider, const uint32 *wanted, uint32 count)
{
	uint32 index;
	for (index = 0U; index < target.irq_count; index++)
		if (target.irqs[index].cell_count == count &&
		    strcmp(target.irqs[index].provider, provider) == 0 &&
		    memcmp(target.irqs[index].cells, wanted, count * sizeof(*wanted)) == 0) return 1;
	return 0;
}

