static void spi_child_select(void *context, uint64 time)
{
	Binding *binding = context;
	(void)time;
	binding->ops->set_chip_select(binding->instance, TRUE);
}

static sint32 spi_child_exchange(void *context, uint8 transmitted,
	uint8 *received, uint64 time)
{
	Binding *binding = context;
	(void)time;
	*received = binding->ops->exchange_byte(binding->instance, transmitted);
	return 0;
}

static void spi_child_deselect(void *context, uint64 time)
{
	Binding *binding = context;
	(void)time;
	binding->ops->set_chip_select(binding->instance, FALSE);
}

static const AthrillSpiChildOps spi_child_ops = {
	spi_child_select, spi_child_exchange, spi_child_deselect
};

static sint32 spi_connection_open(uint32 index, SpiConnection *connection)
{
	AthrillChannelConfig config;
	if (index >= target.binding_count) return -1;
	memset(connection, 0, sizeof(*connection));
	memset(&config, 0, sizeof(config));
	connection->binding = &target.bindings[index];
	config.peripheral_width = 1U; config.memory_width = 1U;
	config.capacity = 1U; config.threshold = 1U; config.burst = 1U;
	config.selection.kind = ATHRILL_CHANNEL_SELECT_CHIP;
	config.selection.value = connection->binding->chip_select;
	config.count_kind = ATHRILL_CHANNEL_COUNT_SELECTION;
	config.directions = ATHRILL_CHANNEL_ALLOW_EXCHANGE;
	if (athrill_channel_create(&config, &connection->channel) != 0) return -1;
	if (athrill_spi_protocol_create(connection->channel, &spi_child_ops,
	    connection->binding, &connection->protocol) != 0) {
		athrill_channel_destroy(connection->channel); return -1;
	}
	connection->time = 1U;
	return 0;
}

static void spi_connection_close(SpiConnection *connection)
{
	athrill_spi_protocol_destroy(connection->protocol);
	athrill_channel_destroy(connection->channel);
}

static sint32 spi_command_read(uint32 index, uint8 command, uint8 *data, uint32 count)
{
	SpiConnection connection;
	uint32 at;
	uint8 received;
	if (spi_connection_open(index, &connection) != 0) return -1;
	if (athrill_spi_select(connection.protocol, connection.binding->chip_select,
	    connection.time++) != 1 ||
	    athrill_spi_exchange(connection.protocol, command, &received,
	    connection.time++) != 0) { spi_connection_close(&connection); return -1; }
	for (at = 0U; at < count; at++)
		if (athrill_spi_exchange(connection.protocol, 0U, &data[at],
		    connection.time++) != 0) { spi_connection_close(&connection); return -1; }
	if (athrill_spi_deselect(connection.protocol, connection.time++) != 0) {
		spi_connection_close(&connection); return -1;
	}
	spi_connection_close(&connection);
	return 0;
}

static sint32 spi_register_read(uint32 index, uint8 address, uint32 dummy_count,
	uint8 *value)
{
	uint8 data[2];
	if (dummy_count > 1U || spi_command_read(index, address | 0x80U,
	    data, dummy_count + 1U) != 0) return -1;
	*value = data[dummy_count];
	return 0;
}

static std_bool i2c_child_start(void *context, std_bool read,
	std_bool repeated, uint64 time)
{
	I2cBinding *binding = context;
	(void)repeated; (void)time;
	return binding->ops->start != NULL && binding->ops->start(binding->instance, read);
}

static std_bool i2c_child_write(void *context, uint8 data, uint64 time)
{
	I2cBinding *binding = context;
	(void)time;
	if (binding->ops->write_byte == NULL) return FALSE;
	binding->ops->write_byte(binding->instance, data);
	return TRUE;
}

static sint32 i2c_child_read(void *context, uint8 *data,
	std_bool master_ack, uint64 time)
{
	I2cBinding *binding = context;
	(void)master_ack; (void)time;
	if (binding->ops->read_byte == NULL) return -1;
	*data = binding->ops->read_byte(binding->instance);
	return 0;
}

static void i2c_child_stop(void *context, uint64 time)
{
	I2cBinding *binding = context;
	(void)time;
	if (binding->ops->stop != NULL) binding->ops->stop(binding->instance);
}

static const AthrillI2cChildOps i2c_child_ops = {
	i2c_child_start, i2c_child_write, i2c_child_read, i2c_child_stop
};

static sint32 i2c_connection_open(uint32 index, I2cConnection *connection)
{
	AthrillChannelConfig config;
	if (index >= target.i2c_binding_count) return -1;
	memset(connection, 0, sizeof(*connection));
	memset(&config, 0, sizeof(config));
	connection->binding = &target.i2c_bindings[index];
	config.peripheral_width = 1U; config.memory_width = 1U;
	config.capacity = 1U; config.threshold = 1U; config.burst = 1U;
	config.selection.kind = ATHRILL_CHANNEL_SELECT_ADDRESS;
	config.selection.value = connection->binding->address;
	config.count_kind = ATHRILL_CHANNEL_COUNT_SELECTION;
	config.directions = ATHRILL_CHANNEL_ALLOW_EXCHANGE;
	if (athrill_channel_create(&config, &connection->channel) != 0) return -1;
	if (athrill_i2c_protocol_create(connection->channel, &i2c_child_ops,
	    connection->binding, &connection->protocol) != 0) {
		athrill_channel_destroy(connection->channel); return -1;
	}
	connection->time = 1U;
	return 0;
}

static void i2c_connection_close(I2cConnection *connection)
{
	athrill_i2c_protocol_destroy(connection->protocol);
	athrill_channel_destroy(connection->channel);
}

static sint32 i2c_write_byte(I2cConnection *connection, uint8 data)
{
	std_bool ack;
	return athrill_i2c_write(connection->protocol, data, &ack,
	    connection->time++) == 0 && ack ? 0 : -1;
}

static sint32 i2c_command_read(uint32 index, uint8 command, uint8 *data, uint32 count)
{
	I2cConnection connection;
	uint32 at;
	if (i2c_connection_open(index, &connection) != 0) return -1;
	if (athrill_i2c_start(connection.protocol, connection.binding->address, FALSE,
	    connection.time++) != 1 || i2c_write_byte(&connection, command) != 0 ||
	    athrill_i2c_stop(connection.protocol, connection.time++) != 0) {
		i2c_connection_close(&connection); return -1;
	}
	if (count != 0U && athrill_i2c_start(connection.protocol,
	    connection.binding->address, TRUE, connection.time++) != 1) {
		i2c_connection_close(&connection); return -1;
	}
	for (at = 0U; at < count; at++)
		if (athrill_i2c_read(connection.protocol, &data[at], at + 1U < count,
		    connection.time++) != 0) { i2c_connection_close(&connection); return -1; }
	if (count != 0U && athrill_i2c_stop(connection.protocol,
	    connection.time++) != 0) { i2c_connection_close(&connection); return -1; }
	i2c_connection_close(&connection);
	return 0;
}

static sint32 i2c_register_read(uint32 index, uint8 address, uint8 *value)
{ return i2c_command_read(index, address, value, 1U); }

static uint8 ms5611_crc4(uint16 *prom)
{
	uint16 remainder = 0U, saved = prom[7];
	uint32 byte, bit;
	prom[7] &= 0xff00U;
	for (byte = 0U; byte < 16U; byte++) {
		remainder ^= (byte & 1U) ? (prom[byte >> 1] & 0xffU) :
		    (prom[byte >> 1] >> 8);
		for (bit = 0U; bit < 8U; bit++)
			remainder = (remainder & 0x8000U) ?
			    (uint16)((remainder << 1) ^ 0x3000U) : (uint16)(remainder << 1);
	}
	prom[7] = saved;
	return (uint8)((remainder >> 12) & 0x0fU);
}

static int ms5611_prom_crc(uint32 index, std_bool spi)
{
	uint16 prom[8];
	uint8 bytes[2], stored;
	uint32 word;
	if ((spi ? spi_command_read(index, 0x1eU, bytes, 0U) :
	    i2c_command_read(index, 0x1eU, bytes, 0U)) != 0) return 0;
	for (word = 0U; word < 8U; word++) {
		uint8 command = (uint8)(0xa0U + 2U * word);
		if ((spi ? spi_command_read(index, command, bytes, 2U) :
		    i2c_command_read(index, command, bytes, 2U)) != 0) return 0;
		prom[word] = (uint16)(((uint16)bytes[0] << 8) | bytes[1]);
	}
	stored = (uint8)(prom[7] & 0x0fU);
	return ms5611_crc4(prom) == stored;
}

