static int trace_contains(const char *needle)
{
	FILE *stream = fopen(pwm_trace_path, "r");
	char line[512];
	if (stream == NULL) return 0;
	while (fgets(line, sizeof(line), stream) != NULL)
		if (strstr(line, needle) != NULL) { fclose(stream); return 1; }
	fclose(stream);
	return 0;
}

